package me.summariseme.app;
import org.json.JSONObject;import android.database.Cursor;import android.provider.OpenableColumns;import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import android.view.*;import android.webkit.*;import android.widget.Toast;import androidx.webkit.WebViewAssetLoader;import androidx.core.content.FileProvider;import java.io.*;import java.util.*;
public class MainActivity extends Activity {
 private WebView web;private String pendingMetadata;private final Map<String,File> exports=new HashMap<>();private final Map<String,String> exportTypes=new HashMap<>();private File pendingDownload;
 private static final String HOST="appassets.androidplatform.net";
 @Override public void onCreate(Bundle saved){super.onCreate(saved);if(Build.VERSION.SDK_INT>=30)getWindow().setDecorFitsSystemWindows(true);web=new WebView(this);web.setBackgroundColor(Color.parseColor("#101b30"));setContentView(web);WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setMediaPlaybackRequiresUserGesture(false);WebView.setWebContentsDebuggingEnabled(BuildConfig.DEBUG);
 WebViewAssetLoader loader=new WebViewAssetLoader.Builder().addPathHandler("/assets/",new WebViewAssetLoader.AssetsPathHandler(this)).addPathHandler("/imports/",path->importResponse(path)).addPathHandler("/recordings/",path->{if(!path.matches("[a-f0-9-]+\\.m4a"))return null;try{return new WebResourceResponse("audio/mp4",null,new FileInputStream(new File(RecordingService.directory(this),path)));}catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",404,"Not found",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}}).build();
 web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){return loader.shouldInterceptRequest(request.getUrl());}@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){Uri url=request.getUrl();if("https".equals(url.getScheme())&&HOST.equals(url.getHost())&&url.getPath()!=null&&url.getPath().startsWith("/assets/"))return false;if(request.isForMainFrame()&&("https".equals(url.getScheme())||"http".equals(url.getScheme())))startActivity(new Intent(Intent.ACTION_VIEW,url));return true;}});
 web.setWebChromeClient(new WebChromeClient(){@Override public void onPermissionRequest(PermissionRequest request){request.deny();}});web.addJavascriptInterface(new NativeBridge(),"AndroidRecorder");web.loadUrl("https://"+HOST+"/assets/index.html");receiveAudio(getIntent());}
 private void startRecording(String metadata){if(isFinishing()||isDestroyed())return;pendingMetadata=metadata;ArrayList<String> permissions=new ArrayList<>();if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)permissions.add(Manifest.permission.RECORD_AUDIO);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)permissions.add(Manifest.permission.POST_NOTIFICATIONS);if(!permissions.isEmpty()){requestPermissions(permissions.toArray(new String[0]),7);return;}launchRecorder(metadata);}
 private void launchRecorder(String metadata){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){RecordingService.setError("Microphone permission is required.");return;}RecordingService.setError("");try{startForegroundService(new Intent(this,RecordingService.class).setAction("begin").putExtra("metadata",metadata));}catch(Exception e){RecordingService.setError("Open the app before starting the microphone.");}}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==7)launchRecorder(pendingMetadata);}
 private File importDirectory(){File dir=new File(getFilesDir(),"imports");dir.mkdirs();return dir;}
 private WebResourceResponse importResponse(String id){if(!id.matches("[a-f0-9-]{36}"))return null;try{JSONObject meta=new JSONObject(new String(java.nio.file.Files.readAllBytes(new File(importDirectory(),id+".json").toPath()),java.nio.charset.StandardCharsets.UTF_8));return new WebResourceResponse(meta.getString("type"),null,new FileInputStream(new File(importDirectory(),id+".audio")));}catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",404,"Not found",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);receiveAudio(intent);}
 private void receiveAudio(Intent intent){if(intent==null||!Intent.ACTION_SEND.equals(intent.getAction()))return;Uri uri=Build.VERSION.SDK_INT>=33?intent.getParcelableExtra(Intent.EXTRA_STREAM,Uri.class):intent.getParcelableExtra(Intent.EXTRA_STREAM);if(uri==null&&intent.getClipData()!=null&&intent.getClipData().getItemCount()>0)uri=intent.getClipData().getItemAt(0).getUri();if(uri!=null)queueAudio(uri);}
 private void queueAudio(Uri uri){if(!"content".equals(uri.getScheme())){Toast.makeText(this,"Choose an audio file from a file provider",Toast.LENGTH_LONG).show();return;}new Thread(()->{String id=UUID.randomUUID().toString();File audio=new File(importDirectory(),id+".audio"),metadata=new File(importDirectory(),id+".json");try{
 String type=getContentResolver().getType(uri),name="Voice note";try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE},null,null,null)){if(c!=null&&c.moveToFirst()){int n=c.getColumnIndex(OpenableColumns.DISPLAY_NAME),z=c.getColumnIndex(OpenableColumns.SIZE);if(n>=0&&!c.isNull(n))name=c.getString(n);if(z>=0&&!c.isNull(z)&&c.getLong(z)>24L*1024*1024)throw new IOException("Audio must be under 24 MB");}}
 String lower=name.toLowerCase(Locale.ROOT);if(lower.matches(".*\\.(opus|ogg|oga)$"))type="audio/ogg";else if(lower.matches(".*\\.(m4a|mp4)$"))type="audio/mp4";else if(lower.endsWith(".mp3"))type="audio/mpeg";else if(lower.endsWith(".wav"))type="audio/wav";else if(lower.endsWith(".webm"))type="audio/webm";if("audio/opus".equals(type)||"application/ogg".equals(type))type="audio/ogg";if("audio/x-m4a".equals(type))type="audio/mp4";if("audio/x-wav".equals(type))type="audio/wav";
 if(type==null||!type.matches("audio/(ogg|mp4|mpeg|wav|webm)"))throw new IOException("Choose an Ogg/Opus, M4A, MP3, WAV or WebM file");
 long total=0;try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(audio)){if(in==null)throw new IOException("Cannot open audio");byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1){total+=n;if(total>24L*1024*1024)throw new IOException("Audio must be under 24 MB");out.write(buffer,0,n);}}if(total==0)throw new IOException("This audio file is empty");
 JSONObject meta=new JSONObject().put("id",id).put("name",name).put("type",type);try(OutputStream out=new FileOutputStream(metadata)){out.write(meta.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 }catch(Exception e){audio.delete();metadata.delete();runOnUiThread(()->Toast.makeText(this,e instanceof IOException?e.getMessage():"Unable to import audio. Share it again or use Upload audio.",Toast.LENGTH_LONG).show());}},"audio-import").start();}
 public class NativeBridge {
  @JavascriptInterface public void pickAudio(){runOnUiThread(()->{try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"audio/*","application/ogg"}),9);}catch(Exception e){Toast.makeText(MainActivity.this,"No file picker available",Toast.LENGTH_LONG).show();}});}
  @JavascriptInterface public String pendingImport(){File[] files=importDirectory().listFiles((dir,name)->name.endsWith(".json"));if(files==null||files.length==0)return "{}";Arrays.sort(files,Comparator.comparingLong(File::lastModified));try{return new String(java.nio.file.Files.readAllBytes(files[0].toPath()),java.nio.charset.StandardCharsets.UTF_8);}catch(Exception e){return "{}";}}
  @JavascriptInterface public void acknowledgeImport(String id){if(!id.matches("[a-f0-9-]{36}"))return;new File(importDirectory(),id+".json").delete();new File(importDirectory(),id+".audio").delete();}

  @JavascriptInterface public int versionCode(){return BuildConfig.VERSION_CODE;}
  @JavascriptInterface public void downloadUpdate(){runOnUiThread(()->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://github.com/nikki0radz/Summarise-me/releases/download/android-preview/Summarise-Me.apk")));}catch(Exception e){Toast.makeText(MainActivity.this,"No browser available to download the update",Toast.LENGTH_LONG).show();}});}

  @JavascriptInterface public void begin(String metadata){runOnUiThread(()->startRecording(metadata));}
  @JavascriptInterface public void command(String action){if(!Arrays.asList("pause","resume","finish","cancel").contains(action))return;runOnUiThread(()->{try{startService(new Intent(MainActivity.this,RecordingService.class).setAction(action));}catch(Exception ignored){}});}
  @JavascriptInterface public String state(){return RecordingService.snapshot(MainActivity.this);}
  @JavascriptInterface public void acknowledge(String id){if(!id.matches("[a-f0-9-]+"))return;new File(RecordingService.directory(MainActivity.this),id+".json").delete();new File(RecordingService.directory(MainActivity.this),id+".m4a").delete();}
  @JavascriptInterface public void setTheme(String hex,boolean light){if(!hex.matches("#[a-fA-F0-9]{6}"))return;runOnUiThread(()->{int color=Color.parseColor(hex);getWindow().setStatusBarColor(color);getWindow().setNavigationBarColor(color);getWindow().getDecorView().setBackgroundColor(color);web.setBackgroundColor(color);if(Build.VERSION.SDK_INT>=29)getWindow().setNavigationBarContrastEnforced(false);int flags=light?View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR:0;getWindow().getDecorView().setSystemUiVisibility(flags);});}
  @JavascriptInterface public synchronized String beginExport(String name,String type){String id=UUID.randomUUID().toString();File dir=new File(getCacheDir(),"exports");dir.mkdirs();String clean=name.replaceAll("[^a-zA-Z0-9._-]","_");File file=new File(dir,id+"-"+clean);exports.put(id,file);exportTypes.put(id,type.startsWith("audio/")?type:"application/octet-stream");return id;}
  @JavascriptInterface public synchronized void appendExport(String id,String base64){File file=exports.get(id);if(file==null)return;try(FileOutputStream out=new FileOutputStream(file,true)){out.write(android.util.Base64.decode(base64,android.util.Base64.DEFAULT));}catch(Exception ignored){}}
  @JavascriptInterface public synchronized void finishExport(String id,boolean share){File file=exports.remove(id);String type=exportTypes.remove(id);if(file==null)return;runOnUiThread(()->{try{if(share){Uri uri=FileProvider.getUriForFile(MainActivity.this,getPackageName()+".files",file);Intent intent=new Intent(Intent.ACTION_SEND).setType(type).putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);intent.setClipData(ClipData.newRawUri("Voice note",uri));startActivity(Intent.createChooser(intent,"Share recording"));}else if(Build.VERSION.SDK_INT>=29){ContentValues values=new ContentValues();values.put(MediaStore.Downloads.DISPLAY_NAME,file.getName().substring(37));values.put(MediaStore.Downloads.MIME_TYPE,type);values.put(MediaStore.Downloads.IS_PENDING,1);Uri uri=getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new IOException();try(OutputStream out=getContentResolver().openOutputStream(uri);InputStream in=new FileInputStream(file)){copy(in,out);}values.clear();values.put(MediaStore.Downloads.IS_PENDING,0);getContentResolver().update(uri,values,null,null);Toast.makeText(MainActivity.this,"Saved to Downloads",Toast.LENGTH_SHORT).show();}else{pendingDownload=file;startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType(type).addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,file.getName().substring(37)),8);}}catch(Exception e){Toast.makeText(MainActivity.this,"Unable to export recording",Toast.LENGTH_LONG).show();}});}
 }
 private static void copy(InputStream in,OutputStream out)throws IOException{byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==9&&result==RESULT_OK&&data!=null&&data.getData()!=null)queueAudio(data.getData());if(request==8&&result==RESULT_OK&&data!=null&&pendingDownload!=null){try(InputStream in=new FileInputStream(pendingDownload);OutputStream out=getContentResolver().openOutputStream(data.getData())){copy(in,out);}catch(Exception ignored){}}}
 @Override public void onBackPressed(){web.evaluateJavascript("(()=>{const dialogs=[...document.querySelectorAll('dialog[open]')];if(dialogs.length){const d=dialogs[dialogs.length-1];const e=new Event('cancel',{cancelable:true});if(d.dispatchEvent(e))d.close();return true}if(!document.getElementById('editor').hidden){document.getElementById('back').click();return true}const conversation=document.getElementById('conversationView');if(conversation&&!conversation.hidden){document.getElementById('conversationBack').click();return true}return false})()",result->{if(!"true".equals(result))moveTaskToBack(true);});}
}


